  .filter(([k, v]) => typeof v === 'string' && k.includes('__'))
  .reduce<Record<string, Record<string, string>>>((acc, [key, value]) => {
    const [root, field] = key.split('__');
    if (!root || !field) return acc;
    acc[root] = {
      ...(acc[root] ?? {}),
