## Creating Responsive Typography

The plugin works with Tailwind's responsive variants:

```html
<h1 class="type-xl md:type-2xl lg:type-3xl">Responsive Heading</h1>
```

## Creating a Modular Scale

You can create a perfect modular scale by using a consistent ratio:

```javascript
// tailwind.config.js
const typographyScales = require('tailwind-typography-scales');

// Function to generate a modular scale
function createModularScale(base, ratio, steps) {
  const scale = {};
  for (let i = -steps; i <= steps; i++) {
    const key = i === 0 ? 'base' : i < 0 ? `n${Math.abs(i)}` : `p${i}`;
    scale[key] = { ratio: Math.pow(ratio, i) };
  }
  return scale;
}

module.exports = {
  // ...
  plugins: [
    typographyScales({
      baseSize: 16,
      scales: createModularScale(1, 1.25, 5), // Creates a scale with ratio 1.25 (major third)
    }),
  ],
}
```

This plugin gives you complete control over your typography while maintaining the utility-first approach of Tailwind CSS.

