```tsx
const { hashShotId, hashLoadingGrace, initializingFromHash } = useHashDeepLink({...});
const { columns: videoColumnsPerRow, itemsPerPage } = useVideoLayoutConfig({...});
const { sortedShots, currentShotIndex, hasPrevious, hasNext } = useNavigationState({...});
